-- ============================================================================
-- fia_manual_release.sql: the rules of the fia migration, tested in one
-- transaction that is rolled back (PRD A3, A4, A5, A6).
--
-- Run it after supabase/migrations/20261022100000_fia_two_gates.sql, as the
-- database owner (postgres), on a local database or on production:
--
--   npx vite-node scripts/fia/run-sql.ts supabase/tests/fia_manual_release.sql
--   (or: psql "$SUPABASE_DB_URL" -f supabase/tests/fia_manual_release.sql)
--
-- It prints one line per case, PASS or FAIL, with the rule it tests, and a
-- last line counting both. Nothing it does survives: every row it writes, the
-- stand-in FSRE reader it installs for the D2 and D5 cases, and its own
-- helpers go with the ROLLBACK at the end. It writes nothing to any fsre*
-- schema; where a case needs a package from the FSRE channel, the stand-in
-- replaces fia_private.fsre_packages() inside this transaction only.
--
-- The package is the SYNTHETIC fixture XCOA (src/data/finance-in-action/
-- fixtures/XCOA.SYNTHETIC.json, embedded below; tests/unit/fiaTwoGates.test.ts
-- holds the copy equal to the file). Its provenance is changed to filings
-- here, inside the transaction, and nowhere else.
-- ============================================================================

BEGIN;

CREATE TEMP TABLE fia_test_result (
  n         serial PRIMARY KEY,
  rule      text NOT NULL,
  case_name text NOT NULL,
  passed    boolean NOT NULL,
  detail    text
) ON COMMIT DROP;

-- check_case: run p_sql, as p_role when given, and record whether it was
-- accepted or refused as p_expect says: 'accept', or the constraint names or
-- SQLSTATEs a refusal may carry, separated by '|'. The statement is rolled
-- back unless p_keep (as the owner only), so a negative case never leaves a
-- row behind for the next one.
CREATE FUNCTION pg_temp.check_case(p_rule text, p_case text, p_sql text, p_expect text,
                                   p_role text DEFAULT NULL, p_keep boolean DEFAULT false)
RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  v_state text;
  v_constraint text;
  v_msg text;
  v_ok boolean;
  v_detail text;
BEGIN
  BEGIN
    IF p_role IS NOT NULL THEN
      EXECUTE format('SET LOCAL ROLE %I', p_role);
    END IF;
    EXECUTE p_sql;
    IF p_expect = 'accept' AND p_keep AND p_role IS NULL THEN
      v_ok := true;
      v_detail := 'accepted';
    ELSE
      RAISE EXCEPTION USING ERRCODE = 'FT001', MESSAGE = 'accepted';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_constraint = CONSTRAINT_NAME, v_msg = MESSAGE_TEXT;
    IF v_state = 'FT001' THEN
      v_ok := p_expect = 'accept';
      v_detail := CASE WHEN v_ok THEN 'accepted' ELSE 'accepted; expected a refusal by ' || p_expect END;
    ELSE
      v_ok := p_expect <> 'accept'
              AND (nullif(v_constraint, '') = ANY (string_to_array(p_expect, '|')) OR v_state = ANY (string_to_array(p_expect, '|')));
      v_detail := format('refused: %s%s, %s', v_state, coalesce(' ' || nullif(v_constraint, ''), ''), left(v_msg, 200));
    END IF;
  END;
  INSERT INTO fia_test_result (rule, case_name, passed, detail) VALUES (p_rule, p_case, v_ok, v_detail);
END
$fn$;

-- check_value: the text p_sql returns, as p_role when given, against p_expected.
CREATE FUNCTION pg_temp.check_value(p_rule text, p_case text, p_sql text, p_expected text, p_role text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  v_got text;
  v_state text;
  v_msg text;
BEGIN
  BEGIN
    IF p_role IS NOT NULL THEN
      EXECUTE format('SET LOCAL ROLE %I', p_role);
    END IF;
    EXECUTE p_sql INTO v_got;
    RAISE EXCEPTION USING ERRCODE = 'FT002', MESSAGE = coalesce(v_got, '<null>');
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_state = RETURNED_SQLSTATE, v_msg = MESSAGE_TEXT;
    IF v_state <> 'FT002' THEN
      v_msg := format('error %s: %s', v_state, left(v_msg, 200));
    END IF;
  END;
  INSERT INTO fia_test_result (rule, case_name, passed, detail)
  VALUES (p_rule, p_case, v_state = 'FT002' AND v_msg = coalesce(p_expected, '<null>'),
          format('got %s, expected %s', v_msg, coalesce(p_expected, '<null>')));
END
$fn$;

