CREATE FUNCTION pg_temp.filings(p_ticker text DEFAULT 'XCOA', p_version text DEFAULT 'XCOA-2025Q4-r1-SYNTHETIC')
RETURNS jsonb LANGUAGE sql AS $fn$
  SELECT jsonb_set(jsonb_set(jsonb_set(pkg, '{meta,provenance}', '"filings"'),
                             '{meta,ticker}', to_jsonb(p_ticker)),
                   '{meta,version}', to_jsonb(p_version))
  FROM fia_test_fixture
$fn$;

-- The INSERT for a package; the columns follow its meta unless given.
CREATE FUNCTION pg_temp.insert_sql(p_pkg jsonb, p_status text DEFAULT 'staged', p_by text DEFAULT NULL,
                                   p_at timestamptz DEFAULT NULL, p_ticker text DEFAULT NULL,
                                   p_version text DEFAULT NULL, p_hash text DEFAULT NULL)
RETURNS text LANGUAGE sql AS $fn$
  SELECT format('INSERT INTO fia.manual_release (ticker, version, content_hash, package, status, approved_by, approved_at) '
                'VALUES (%L, %L, %L, %L::jsonb, %L, %L, %L)',
                coalesce(p_ticker, p_pkg #>> '{meta,ticker}'), coalesce(p_version, p_pkg #>> '{meta,version}'),
                coalesce(p_hash, p_pkg #>> '{meta,contentHash}'), p_pkg, p_status, p_by, p_at)
$fn$;

-- A gate marked failed.
CREATE FUNCTION pg_temp.with_failed_gate(p_pkg jsonb) RETURNS jsonb LANGUAGE sql AS $fn$
  SELECT jsonb_set(p_pkg, '{workpaper,gates,0,status}', '"failed"')
$fn$;

-- ----------------------------------------------------------------------------
-- The contract as the database holds it (D4)
-- ----------------------------------------------------------------------------

SELECT pg_temp.check_value('D4 contract', 'fia.contract_schema holds proposal-v3.1, a valid JSON Schema (draft-07)',
  $q$SELECT string_agg(version || ':' || extensions.jsonschema_is_valid(schema::json)::text || ':' || (schema->>'$schema'), ',') FROM fia.contract_schema$q$,
  'proposal-v3.1:true:http://json-schema.org/draft-07/schema#');
SELECT pg_temp.check_value('D4 contract', 'the SYNTHETIC fixture as filed matches the stored schema',
  $q$SELECT extensions.jsonb_matches_schema(c.schema::json, f.pkg)::text FROM fia.contract_schema c, fia_test_fixture f$q$, 'true');
SELECT pg_temp.check_value('D4 contract', 'the schema''s $ref definitions are applied (a bad rowRef does not match)',
  $q$SELECT extensions.jsonb_matches_schema(c.schema::json, jsonb_set(f.pkg, '{driverTree,nodes,0,rowRef}', '"nowhere"'))::text FROM fia.contract_schema c, fia_test_fixture f$q$, 'false');
SELECT pg_temp.check_case('D4 contract', 'the stored contract cannot be changed',
  $q$UPDATE fia.contract_schema SET schema = '{}'::jsonb$q$, 'contract_schema_insert_only');
SELECT pg_temp.check_case('D4 contract', 'the stored contract cannot be deleted',
  $q$DELETE FROM fia.contract_schema$q$, 'contract_schema_insert_only');
SELECT pg_temp.check_case('D4 contract', 'the stored contract cannot be truncated',
  $q$TRUNCATE fia.contract_schema$q$, 'contract_schema_no_truncate');

-- ----------------------------------------------------------------------------
-- The FSRE channel, as it is (before the stand-in below replaces it)
-- ----------------------------------------------------------------------------

-- (The query is chosen as text: a statement naming fsre_published.model_packages
-- does not parse on a database without it.)
SELECT pg_temp.check_value('FSRE reader', 'reads every row of fsre_published.model_packages, or none where it does not exist',
  CASE WHEN to_regclass('fsre_published.model_packages') IS NULL
       THEN $q$SELECT ((SELECT count(*) FROM fia_private.fsre_packages()) = 0)::text$q$
       ELSE $q$SELECT ((SELECT count(*) FROM fia_private.fsre_packages()) = (SELECT count(*) FROM fsre_published.model_packages))::text$q$
  END, 'true');
SELECT pg_temp.check_value('FSRE reader', 'anon reads fia.model_packages with the FSRE channel in it, without an error',
  $q$SELECT (count(*) >= 0)::text FROM fia.model_packages$q$, 'true', 'anon');
SELECT pg_temp.check_value('A7 fsre untouched', 'no view outside fsre* depends on an fsre* object',
  $q$SELECT count(DISTINCT r.ev_class)::text
     FROM pg_depend d
     JOIN pg_rewrite r ON d.classid = 'pg_rewrite'::regclass AND d.objid = r.oid
     JOIN pg_class dep ON dep.oid = r.ev_class
     JOIN pg_class ref ON d.refclassid = 'pg_class'::regclass AND d.refobjid = ref.oid
     WHERE ref.relnamespace::regnamespace::text LIKE 'fsre%' AND dep.relnamespace::regnamespace::text NOT LIKE 'fsre%'$q$, '0');

-- ----------------------------------------------------------------------------
-- R1: the manual channel
-- ----------------------------------------------------------------------------

-- The positive case every rule shares: the fixture, as filings, staged.
SELECT pg_temp.check_case('R1 positive', 'a filings package that matches the contract is staged',
  pg_temp.insert_sql(pg_temp.filings()), 'accept', NULL, true);

-- The JSON Schema (D4)
SELECT pg_temp.check_case('R1 JSON Schema', 'a cell without a kind is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-schema-1') #- '{sheets,0,rows,0,cells,0,kind}'), 'manual_release_contract');
SELECT pg_temp.check_case('R1 JSON Schema', 'a key the contract does not have is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-schema-2') || '{"channel": "manual"}'), 'manual_release_contract');
SELECT pg_temp.check_case('R1 JSON Schema', 'a rowRef that is not <sheet>!<row> is refused',
  pg_temp.insert_sql(jsonb_set(pg_temp.filings('XCOA', 'r-schema-3'), '{driverTree,nodes,0,rowRef}', '"nowhere"')), 'manual_release_contract');
SELECT pg_temp.check_case('R1 JSON Schema', 'a sourced cell without a source is refused',
  pg_temp.insert_sql(jsonb_set(pg_temp.filings('XCOA', 'r-schema-4'), '{sheets,0,rows,0,cells,0}', '{"kind": "sourced", "value": 1}')), 'manual_release_contract');
SELECT pg_temp.check_case('R1 JSON Schema', 'a meta.status outside the enumeration is refused',
  pg_temp.insert_sql(jsonb_set(pg_temp.filings('XCOA', 'r-schema-5'), '{meta,status}', '"live"')), 'manual_release_contract');
SELECT pg_temp.check_case('R1 JSON Schema', 'a staged row edited into a package that does not match is refused',
  $q$UPDATE fia.manual_release SET package = package #- '{workpaper,gates}' WHERE ticker = 'XCOA' AND version = 'XCOA-2025Q4-r1-SYNTHETIC'$q$,
  'manual_release_contract');

-- The columns against package.meta
SELECT pg_temp.check_case('R1 meta.ticker', 'a ticker column other than meta.ticker is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-meta-1'), p_ticker => 'XCOB'), 'manual_release_meta_ticker');
SELECT pg_temp.check_case('R1 meta.ticker', 'a ticker that is not 2 to 8 capitals or digits is refused',
  pg_temp.insert_sql(pg_temp.filings('xcoa', 'r-meta-2')), 'manual_release_contract|manual_release_ticker_format');
SELECT pg_temp.check_case('R1 meta.version', 'a version column other than meta.version is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-meta-3'), p_version => 'r-meta-3-other'), 'manual_release_meta_version');
SELECT pg_temp.check_case('R1 meta.contentHash', 'a content_hash column other than meta.contentHash is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-meta-4'), p_hash => repeat('0', 64)), 'manual_release_meta_content_hash');
SELECT pg_temp.check_case('R1 meta.contentHash', 'a content_hash that is not 64 lower-case hex digits is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-meta-5'), p_hash => 'ABC123'), 'manual_release_content_hash_format|manual_release_meta_content_hash');

-- Provenance
SELECT pg_temp.check_case('R1 provenance', 'the SYNTHETIC fixture as filed (provenance synthetic) is refused',
  pg_temp.insert_sql((SELECT jsonb_set(pkg, '{meta,version}', '"r-prov-1"') FROM fia_test_fixture)), 'manual_release_provenance_filings');
SELECT pg_temp.check_case('R1 provenance', 'provenance fixture is refused',
  pg_temp.insert_sql(jsonb_set(pg_temp.filings('XCOA', 'r-prov-2'), '{meta,provenance}', '"fixture"')), 'manual_release_provenance_filings');

-- Published needs an approver and a time
SELECT pg_temp.check_case('R1 published approved', 'published without approved_by is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-appr-1'), 'published', NULL, '2026-10-22 09:00+07'), 'manual_release_published_approved');
SELECT pg_temp.check_case('R1 published approved', 'published with a blank approved_by is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-appr-2'), 'published', '   ', '2026-10-22 09:00+07'), 'manual_release_published_approved');
SELECT pg_temp.check_case('R1 published approved', 'published without approved_at is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-appr-3'), 'published', 'Dika Gustiana Irawan', NULL), 'manual_release_published_approved');
SELECT pg_temp.check_case('R1 published approved', 'a staged row moved to published without an approver is refused',
  $q$UPDATE fia.manual_release SET status = 'published' WHERE ticker = 'XCOA' AND version = 'XCOA-2025Q4-r1-SYNTHETIC'$q$,
  'manual_release_published_approved');
SELECT pg_temp.check_case('R1 approval time', 'published with an approval time in the future is refused (it would win D2 until withdrawn)',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-time-1'), 'published', 'Dika Gustiana Irawan', now() + interval '1 day'),
  'manual_release_approved_not_future');
SELECT pg_temp.check_case('R1 approval time', 'a staged row moved to published with a future approval time is refused',
  $q$UPDATE fia.manual_release SET status = 'published', approved_by = 'Dika Gustiana Irawan', approved_at = now() + interval '1 day'
     WHERE ticker = 'XCOA' AND version = 'XCOA-2025Q4-r1-SYNTHETIC'$q$, 'manual_release_approved_not_future');
SELECT pg_temp.check_case('R1 approval time', 'published with the approval time now is accepted',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-time-2'), 'published', 'Dika Gustiana Irawan', now()), 'accept');
SELECT pg_temp.check_case('R1 published approved', 'published with an approver and a time is accepted',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'XCOA-r2'), 'published', 'Dika Gustiana Irawan', '2026-10-22 09:00+07'), 'accept', NULL, true);

-- A failed gate (D5)
SELECT pg_temp.check_case('R1 failed gate', 'published with a failed gate is refused',
  pg_temp.insert_sql(pg_temp.with_failed_gate(pg_temp.filings('XCOA', 'r-gate-1')), 'published', 'Dika Gustiana Irawan', '2026-10-22 09:00+07'),
  'manual_release_published_no_failed_gate');
SELECT pg_temp.check_case('R1 failed gate', 'a staged row with a failed gate moved to published is refused',
  $q$UPDATE fia.manual_release SET package = jsonb_set(package, '{workpaper,gates,0,status}', '"failed"'), status = 'published',
       approved_by = 'Dika Gustiana Irawan', approved_at = '2026-10-22 09:00+07'
     WHERE ticker = 'XCOA' AND version = 'XCOA-2025Q4-r1-SYNTHETIC'$q$, 'manual_release_published_no_failed_gate');
SELECT pg_temp.check_case('R1 failed gate', 'staged with a failed gate is accepted (it is not shown)',
  pg_temp.insert_sql(pg_temp.with_failed_gate(pg_temp.filings('XCOA', 'r-gate-2'))), 'accept');
SELECT pg_temp.check_case('R1 failed gate', 'published with passed and passed_with_escalation gates is accepted',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-gate-3'), 'published', 'Dika Gustiana Irawan', '2026-10-22 09:00+07'), 'accept');

-- One row per (ticker, version)
SELECT pg_temp.check_case('R1 unique', 'a second row for the same ticker and version is refused',
  pg_temp.insert_sql(pg_temp.filings()), 'manual_release_pkey|23505');
SELECT pg_temp.check_case('R1 unique', 'the same ticker under a new version is accepted',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-uniq-1')), 'accept');

-- Status: what a row may be, and what it may become
SELECT pg_temp.check_case('R1 status', 'a new row that is withdrawn is refused',
  pg_temp.insert_sql(pg_temp.filings('XCOA', 'r-status-1'), 'withdrawn'), 'manual_release_new_row_status');
SELECT pg_temp.check_case('R1 status', 'a status outside staged, published and withdrawn is refused',
  $q$UPDATE fia.manual_release SET status = 'live' WHERE ticker = 'XCOA' AND version = 'XCOA-2025Q4-r1-SYNTHETIC'$q$,
  'manual_release_status_known');
SELECT pg_temp.check_case('R1 staged editable', 'a staged row can be edited',
  $q$UPDATE fia.manual_release SET note = 'staged, edited' WHERE ticker = 'XCOA' AND version = 'XCOA-2025Q4-r1-SYNTHETIC'$q$, 'accept');
SELECT pg_temp.check_case('R1 staged editable', 'a staged row can be deleted',
  $q$DELETE FROM fia.manual_release WHERE ticker = 'XCOA' AND version = 'XCOA-2025Q4-r1-SYNTHETIC'$q$, 'accept');
SELECT pg_temp.check_value('R1 staged editable', 'an edit keeps created_by and created_at',
  $q$WITH e AS (UPDATE fia.manual_release SET created_by = 'someone else', created_at = '2000-01-01', note = 'edited'
               WHERE ticker = 'XCOA' AND version = 'XCOA-2025Q4-r1-SYNTHETIC' RETURNING created_by, created_at)
     SELECT (created_by = current_user AND created_at = now())::text FROM e$q$, 'true');

-- A published row is locked: only withdrawn
SELECT pg_temp.check_case('R1 published locked', 'its package cannot be edited',
  $q$UPDATE fia.manual_release SET package = jsonb_set(package, '{meta,name}', '"Another name"') WHERE ticker = 'XCOA' AND version = 'XCOA-r2'$q$,
  'manual_release_published_locked');
SELECT pg_temp.check_case('R1 published locked', 'its note cannot be edited',
  $q$UPDATE fia.manual_release SET note = 'changed' WHERE ticker = 'XCOA' AND version = 'XCOA-r2'$q$, 'manual_release_published_locked');
SELECT pg_temp.check_case('R1 published locked', 'its approver cannot be edited',
  $q$UPDATE fia.manual_release SET approved_by = 'Someone else' WHERE ticker = 'XCOA' AND version = 'XCOA-r2'$q$, 'manual_release_published_locked');
SELECT pg_temp.check_case('R1 published locked', 'it cannot go back to staged',
  $q$UPDATE fia.manual_release SET status = 'staged' WHERE ticker = 'XCOA' AND version = 'XCOA-r2'$q$, 'manual_release_published_locked');
SELECT pg_temp.check_case('R1 published locked', 'it cannot be withdrawn and edited in one statement',
  $q$UPDATE fia.manual_release SET status = 'withdrawn', note = 'why' WHERE ticker = 'XCOA' AND version = 'XCOA-r2'$q$, 'manual_release_published_locked');
SELECT pg_temp.check_case('R1 published locked', 'it cannot be deleted',
  $q$DELETE FROM fia.manual_release WHERE ticker = 'XCOA' AND version = 'XCOA-r2'$q$, 'manual_release_published_locked');
SELECT pg_temp.check_case('R1 published locked', 'the table cannot be truncated',
  $q$TRUNCATE fia.manual_release$q$, 'manual_release_no_truncate');
SELECT pg_temp.check_case('R1 published locked', 'it can be withdrawn',
  $q$UPDATE fia.manual_release SET status = 'withdrawn' WHERE ticker = 'XCOA' AND version = 'XCOA-r2'$q$, 'accept', NULL, true);

-- Withdrawn is final
SELECT pg_temp.check_case('R1 withdrawn final', 'a withdrawn row cannot be published again',
  $q$UPDATE fia.manual_release SET status = 'published' WHERE ticker = 'XCOA' AND version = 'XCOA-r2'$q$, 'manual_release_withdrawn_final');
SELECT pg_temp.check_case('R1 withdrawn final', 'a withdrawn row cannot be deleted',
  $q$DELETE FROM fia.manual_release WHERE ticker = 'XCOA' AND version = 'XCOA-r2'$q$, 'manual_release_withdrawn_final');
SELECT pg_temp.check_value('R1 withdrawn final', 'a withdrawn row is not in fia.model_packages',
  $q$SELECT count(*)::text FROM fia.model_packages WHERE ticker = 'XCOA' AND channel = 'manual' AND version = 'XCOA-r2'$q$, '0');

-- The guards fire in every replication role (a restore's session_replication_role = replica skips ordinary triggers)
SELECT pg_temp.check_value('R1 guards always on', 'the four guard triggers are ENABLE ALWAYS',
  $q$SELECT string_agg(tgname || ':' || tgenabled::text, ',' ORDER BY tgname) FROM pg_trigger
     WHERE tgrelid IN ('fia.manual_release'::regclass, 'fia.contract_schema'::regclass) AND NOT tgisinternal$q$,
  'contract_schema_insert_only:A,contract_schema_no_truncate:A,manual_release_guard:A,manual_release_no_truncate:A');

-- No grant, row security on, no policy
SELECT pg_temp.check_value('R1 no grant', 'row security is on for both tables, with no policy',
  $q$SELECT string_agg(c.relname || ':' || c.relrowsecurity::text || ':' ||
                       (SELECT count(*) FROM pg_policy p WHERE p.polrelid = c.oid)::text, ',' ORDER BY c.relname)
     FROM pg_class c WHERE c.oid IN ('fia.manual_release'::regclass, 'fia.contract_schema'::regclass)$q$,
  'contract_schema:true:0,manual_release:true:0');
SELECT pg_temp.check_value('R1 no grant', 'neither anon nor authenticated holds any privilege on either table',
  $q$SELECT count(*)::text FROM (VALUES ('anon'), ('authenticated')) AS r(role),
            (VALUES ('fia.manual_release'), ('fia.contract_schema')) AS t(tbl),
            (VALUES ('SELECT'), ('INSERT'), ('UPDATE'), ('DELETE'), ('TRUNCATE'), ('REFERENCES'), ('TRIGGER')) AS p(priv)
     WHERE has_table_privilege(r.role, t.tbl, p.priv)$q$, '0');

-- ----------------------------------------------------------------------------
-- D2 and D5 across both channels (A4, A5)
-- ----------------------------------------------------------------------------

-- The FSRE channel's stand-in, for this transaction only: the rows of a
-- temporary table. It runs as its owner, so anon can read it through the view
-- without a grant on this session's temporary schema; the real reader's
-- access as anon is the 'FSRE reader' case above.
CREATE TEMP TABLE fia_test_fsre (
  ticker text, version text, content_hash text, approved_by text, approved_at timestamptz, package jsonb
) ON COMMIT DROP;

CREATE OR REPLACE FUNCTION fia_private.fsre_packages()
RETURNS TABLE (ticker text, version text, content_hash text, approved_by text, approved_at timestamptz, package jsonb)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog AS $fn$
  SELECT t.ticker, t.version, t.content_hash, t.approved_by, t.approved_at, t.package FROM pg_temp.fia_test_fsre t
$fn$;

-- An FSRE row as the FSRE view gives it.
CREATE FUNCTION pg_temp.fsre_row(p_ticker text, p_version text, p_at timestamptz, p_pkg jsonb DEFAULT NULL)
RETURNS void LANGUAGE sql AS $fn$
  INSERT INTO fia_test_fsre
  SELECT p_ticker, p_version, pkg #>> '{meta,contentHash}', 'FSRE approver', p_at,
         jsonb_set(jsonb_set(pkg, '{meta,status}', '"published"'), '{workpaper,approvedBy}', '"FSRE approver"')
  FROM (SELECT coalesce(p_pkg, pg_temp.filings(p_ticker, p_version)) AS pkg) AS s
$fn$;

-- A published manual row.
CREATE FUNCTION pg_temp.manual_row(p_ticker text, p_version text, p_at timestamptz, p_pkg jsonb DEFAULT NULL)
RETURNS void LANGUAGE plpgsql AS $fn$
BEGIN
  EXECUTE pg_temp.insert_sql(coalesce(p_pkg, pg_temp.filings(p_ticker, p_version)), 'published', 'Dika Gustiana Irawan', p_at);
END
$fn$;

SELECT pg_temp.manual_row('TMAN', 'TMAN-r1', '2026-10-01 10:00+00');                 -- manual only
SELECT pg_temp.fsre_row('TFSR', 'TFSR-f1', '2026-10-01 10:00+00');                   -- FSRE only
SELECT pg_temp.fsre_row('TNEW', 'TNEW-f1', '2026-10-01 10:00+00');                   -- manual newer
SELECT pg_temp.manual_row('TNEW', 'TNEW-m1', '2026-10-02 10:00+00');
SELECT pg_temp.fsre_row('TOLD', 'TOLD-f1', '2026-10-03 10:00+00');                   -- FSRE newer
SELECT pg_temp.manual_row('TOLD', 'TOLD-m1', '2026-10-02 10:00+00');
SELECT pg_temp.fsre_row('TTIE', 'TTIE-f1', '2026-10-02 10:00:00.123456+00');         -- an exact tie
SELECT pg_temp.manual_row('TTIE', 'TTIE-m1', '2026-10-02 17:00:00.123456+07');
SELECT pg_temp.fsre_row('TNUL', 'TNUL-f1', NULL);                                    -- FSRE approved_at null
SELECT pg_temp.manual_row('TNUL', 'TNUL-m1', '2020-01-01 00:00+00');
SELECT pg_temp.fsre_row('TNUF', 'TNUF-f1', NULL);                                    -- FSRE null, alone
SELECT pg_temp.manual_row('TTWO', 'TTWO-m1', '2026-10-01 10:00+00');                 -- two manual versions
SELECT pg_temp.manual_row('TTWO', 'TTWO-m2', '2026-10-05 10:00+00');
SELECT pg_temp.fsre_row('TFFG', 'TFFG-f1', '2026-10-09 10:00+00',                    -- FSRE failed gate, alone
  pg_temp.with_failed_gate(pg_temp.filings('TFFG', 'TFFG-f1')));
SELECT pg_temp.fsre_row('TFGN', 'TFGN-f2', '2026-10-09 10:00+00',                    -- FSRE newer but failed, manual older
  pg_temp.with_failed_gate(pg_temp.filings('TFGN', 'TFGN-f2')));
SELECT pg_temp.manual_row('TFGN', 'TFGN-m1', '2026-10-01 10:00+00');
SELECT pg_temp.check_case('A5 failed gate', 'a manual row with a failed gate cannot be published, so cannot reach the view',
  pg_temp.insert_sql(pg_temp.with_failed_gate(pg_temp.filings('TMFG', 'TMFG-m1')), 'published', 'Dika Gustiana Irawan', '2026-10-09 10:00+00'),
  'manual_release_published_no_failed_gate');
SELECT pg_temp.check_case('A5 failed gate', 'a manual row with a failed gate can be staged',
  pg_temp.insert_sql(pg_temp.with_failed_gate(pg_temp.filings('TMFS', 'TMFS-m1'))), 'accept', NULL, true);

CREATE FUNCTION pg_temp.shown(p_ticker text) RETURNS text LANGUAGE sql AS $fn$
  SELECT string_agg(channel || ':' || version, ',') FROM fia.model_packages WHERE ticker = p_ticker
$fn$;

SELECT pg_temp.check_value('A4 D2', 'a ticker only in the manual channel is shown from it',
  $q$SELECT pg_temp.shown('TMAN')$q$, 'manual:TMAN-r1');
SELECT pg_temp.check_value('A4 D2', 'a ticker only in the FSRE channel is shown from it',
  $q$SELECT pg_temp.shown('TFSR')$q$, 'fsre:TFSR-f1');
SELECT pg_temp.check_value('A4 D2', 'in both, the more recent approval wins: manual',
  $q$SELECT pg_temp.shown('TNEW')$q$, 'manual:TNEW-m1');
SELECT pg_temp.check_value('A4 D2', 'in both, the more recent approval wins: FSRE',
  $q$SELECT pg_temp.shown('TOLD')$q$, 'fsre:TOLD-f1');
SELECT pg_temp.check_value('A4 D2', 'in both with exactly the same approved_at (to the microsecond, other zone), FSRE wins',
  $q$SELECT pg_temp.shown('TTIE')$q$, 'fsre:TTIE-f1');
SELECT pg_temp.check_value('A4 D2', 'an FSRE approved_at that is null loses to any manual approval',
  $q$SELECT pg_temp.shown('TNUL')$q$, 'manual:TNUL-m1');
SELECT pg_temp.check_value('A4 D2', 'an FSRE row with a null approved_at and no rival is shown',
  $q$SELECT pg_temp.shown('TNUF')$q$, 'fsre:TNUF-f1');
SELECT pg_temp.check_value('A4 D2', 'two published manual versions: the more recent approval wins',
  $q$SELECT pg_temp.shown('TTWO')$q$, 'manual:TTWO-m2');
SELECT pg_temp.check_value('A4 D2', 'one row per ticker',
  $q$SELECT (count(*) = count(DISTINCT ticker))::text FROM fia.model_packages$q$, 'true');
SELECT pg_temp.check_value('A4 D2', 'the manual package says published, with the row''s approver and time (UTC), and no channel key',
  $q$SELECT concat_ws(' | ', package #>> '{meta,status}', package #>> '{workpaper,approvedBy}', package #>> '{workpaper,approvedAt}',
                      (package ? 'channel')::text, approved_by, channel)
     FROM fia.model_packages WHERE ticker = 'TNEW'$q$,
  'published | Dika Gustiana Irawan | 2026-10-02T10:00:00Z | false | Dika Gustiana Irawan | manual');
SELECT pg_temp.check_value('A4 D2', 'the view has the columns of PRD R2, in order',
  $q$SELECT string_agg(attname, ',' ORDER BY attnum) FROM pg_attribute WHERE attrelid = 'fia.model_packages'::regclass AND attnum > 0$q$,
  'ticker,version,channel,content_hash,approved_by,approved_at,package');
SELECT pg_temp.check_value('A4 D2', 'staged rows are not shown',
  $q$SELECT coalesce(pg_temp.shown('TMFS'), 'none')$q$, 'none');

SELECT pg_temp.check_value('A5 failed gate', 'an FSRE package with a failed gate is not shown',
  $q$SELECT coalesce(pg_temp.shown('TFFG'), 'none')$q$, 'none');
SELECT pg_temp.check_value('A5 failed gate', 'a newer FSRE package with a failed gate gives way to the older manual one',
  $q$SELECT pg_temp.shown('TFGN')$q$, 'manual:TFGN-m1');
SELECT pg_temp.check_value('A5 failed gate', 'no package in the view has a failed gate',
  $q$SELECT count(*)::text FROM fia.model_packages WHERE jsonb_path_exists(package, '$.workpaper.gates[*] ? (@.status == "failed")')$q$, '0');

-- ----------------------------------------------------------------------------
-- A6: what anon (and authenticated) can do
-- ----------------------------------------------------------------------------

SELECT pg_temp.check_value('A6 anon', 'anon reads fia.model_packages, both channels',
  $q$SELECT string_agg(ticker || ':' || channel, ',' ORDER BY ticker) FROM fia.model_packages WHERE ticker IN ('TMAN', 'TFSR')$q$,
  'TFSR:fsre,TMAN:manual', 'anon');
SELECT pg_temp.check_case('A6 anon', 'anon cannot read fia.manual_release',
  $q$SELECT count(*) FROM fia.manual_release$q$, '42501', 'anon');
SELECT pg_temp.check_case('A6 anon', 'anon cannot insert into fia.manual_release',
  pg_temp.insert_sql(pg_temp.filings('TANO', 'TANO-m1')), '42501', 'anon');
SELECT pg_temp.check_case('A6 anon', 'anon cannot update fia.manual_release',
  $q$UPDATE fia.manual_release SET note = 'x'$q$, '42501', 'anon');
SELECT pg_temp.check_case('A6 anon', 'anon cannot delete from fia.manual_release',
  $q$DELETE FROM fia.manual_release$q$, '42501', 'anon');
SELECT pg_temp.check_case('A6 anon', 'anon cannot read fia.contract_schema',
  $q$SELECT count(*) FROM fia.contract_schema$q$, '42501', 'anon');
SELECT pg_temp.check_case('A6 anon', 'anon cannot write fia.contract_schema',
  $q$INSERT INTO fia.contract_schema (version, schema) VALUES ('x', '{}')$q$, '42501', 'anon');
SELECT pg_temp.check_value('A6 anon', 'anon holds SELECT on fia.model_packages and no other privilege on it; authenticated holds none',
  $q$SELECT string_agg(r.role || ':' || p.priv, ',' ORDER BY r.role, p.priv)
     FROM (VALUES ('anon'), ('authenticated')) AS r(role),
          (VALUES ('SELECT'), ('INSERT'), ('UPDATE'), ('DELETE'), ('TRUNCATE'), ('REFERENCES'), ('TRIGGER')) AS p(priv)
     WHERE has_table_privilege(r.role, 'fia.model_packages', p.priv)$q$, 'anon:SELECT');
SELECT pg_temp.check_value('A6 anon', 'of fia_private, anon may execute the FSRE reader only (the view calls it), and use the schema not at all',
  $q$SELECT concat_ws(' | ',
       has_schema_privilege('anon', 'fia_private', 'USAGE')::text,
       (SELECT string_agg(p.proname, ',' ORDER BY p.proname) FROM pg_proc p
         WHERE p.pronamespace = 'fia_private'::regnamespace AND has_function_privilege('anon', p.oid, 'EXECUTE')),
       (SELECT count(*) FROM pg_proc p
         WHERE p.pronamespace = 'fia_private'::regnamespace AND has_function_privilege('authenticated', p.oid, 'EXECUTE'))::text)$q$,
  'false | fsre_packages | 0');
SELECT pg_temp.check_case('A6 anon', 'anon cannot call the FSRE reader by name',
  $q$SELECT count(*) FROM fia_private.fsre_packages()$q$, '42501', 'anon');
SELECT pg_temp.check_case('A6 authenticated', 'authenticated cannot read fia.manual_release',
  $q$SELECT count(*) FROM fia.manual_release$q$, '42501', 'authenticated');
SELECT pg_temp.check_case('A6 authenticated', 'authenticated cannot insert into fia.manual_release',
  pg_temp.insert_sql(pg_temp.filings('TAUT', 'TAUT-m1')), '42501', 'authenticated');
SELECT pg_temp.check_case('A6 authenticated', 'authenticated cannot read fia.contract_schema',
  $q$SELECT count(*) FROM fia.contract_schema$q$, '42501', 'authenticated');

-- ----------------------------------------------------------------------------
-- The result, then nothing kept
-- ----------------------------------------------------------------------------

SELECT line FROM (
  SELECT n, CASE WHEN passed THEN 'PASS' ELSE 'FAIL' END || '  ' || rule || ': ' || case_name || '  (' || detail || ')' AS line
  FROM fia_test_result
  UNION ALL
  SELECT 1000000, format('fia_manual_release: %s PASS, %s FAIL', count(*) FILTER (WHERE passed), count(*) FILTER (WHERE NOT passed))
  FROM fia_test_result
) AS r ORDER BY n;

ROLLBACK;
